mapper.select:
select bucket::date as anchor_date, count(*) as story_count, (array_agg(title order by published_at desc, id desc))[1] as lead_title from ( select c.id, c.published_at, coalesce(c.title_zh, c.original_title) as title,
date_trunc('week', c.published_at at time zone 'Asia/Shanghai') date_trunc('month', c.published_at at time zone 'Asia/Shanghai') date_trunc('day', c.published_at at time zone 'Asia/Shanghai')
as bucket from content.content_item c where ) report_rows group by bucket order by bucket desc limit #{limit}
